import { useState } from 'react';
import StatusMark, { type StatusMarkStatus } from '../../../.upstream/src/ts-default/Micro/StatusMark/StatusMark';
import { DemoPanel } from '../../shared/demo-support';
import styles from '../../shared/micro-demos.module.css';
import {componentClasses} from '../../shared/class-names';
const cn=(names:string)=>componentClasses(styles,names);

const labels: Record<StatusMarkStatus, string> = { pending: '等待中', running: '执行中', done: '已完成', failed: '失败', cancelled: '已取消' };
const states: StatusMarkStatus[] = ['pending', 'running', 'done', 'failed', 'cancelled'];
export default function StatusMarkDemo() {
  const [status, setStatus] = useState<StatusMarkStatus>('running');
  const [progress, setProgress] = useState(/*__AW_STATE_state.progress__*/);
  const [determinate, setDeterminate] = useState(/*__AW_STATE_state.determinate__*/);
  return <DemoPanel title="Status Mark · 状态图标"><div className={cn("aw-micro-stack")}>
    <StatusMark status={status} progress={determinate ? progress : undefined} label={labels[status]}      /*__AW_PROPS_t0__*/  />
    <div className={cn("aw-micro-controls")}>{states.map(value => <button className={styles['aw-micro-action']} key={value}  aria-pressed={status === value} onClick={() => setStatus(value)} /*__AW_PROPS_t1__*/ >{labels[value]}</button>)}</div>
    <label className={cn("aw-micro-field")}>模拟进度 {Math.round(progress * 100)}%<input    value={Math.round(progress * 100)} onChange={event => { setDeterminate(true); setProgress(Number(event.target.value) / 100); setStatus('running'); }} /*__AW_PROPS_t2__*/  /></label>
    <div className={cn("aw-micro-controls")}><button className={styles['aw-micro-action']}  aria-pressed={!determinate} onClick={() => { setDeterminate(value => !value); setStatus('running'); }} /*__AW_PROPS_t3__*/ >{determinate ? '切换不定进度' : '切换明确进度'}</button></div>
    <p className={cn("aw-micro-status")} role="status" aria-live="polite">本地任务状态：{labels[status]}</p>
  </div></DemoPanel>;
}
